#!/usr/bin/env node
// SPDX-License-Identifier: AGPL-3.0-only
/**
 * The one table of the MEASURES THAT COUNT (worker-tasks, standing direction of 2026-11-14), GENERATED, never typed:
 *
 *   1. worlds on schema + acts (count)                     worlds/<w>/schema.sop (the generated or hand-declared schema worlds), pilots listed apart
 *   2. hand-written language lines in tab worlds           patterns / lexicon / templates / operations ... of every tab world, generated files and tests left out
 *   3. general lines still in PSys2                        docs/host-boundary.md "General lines still in PSys2" (live count for the world modules) + the knowledge inventory
 *   4. reuse number per world                              docs/library-reuse-report.md (the library's report, a copy)
 *   5. coverage grid holes                                 docs/webchat/coverage-grid.json (scripts/coverage-grid.mjs): k.actions verbs x kinds x values, judged by the state difference
 *   6. cross-world turns                                   on the owner logs (replayed, from build-system-map) and the failure ledger (cross-world causes)
 *   7. pairs of worlds that cooperate                      T1-T3 cells of the case corpus (scripts/exp-transfer.mjs): a pair counts when one cell is right
 *   8. cases in the corpus                                 training/eval/cases.jsonl (scripts/update-cases.mjs), and the right-to-wrong changes of the last run
 *   9. the scaling indicators of Q10 item 1                a new world from a schema alone (60 natural requests), the robustness sets (rules config), cross-world captures (target 0), the richest world on acts:
 *                                                          training/eval/indicators.json (scripts/indicators.mjs), the captures counted live from the corpus
 * Accuracy sets appear as a guard column only (owner logs, T1-T3, grid judged): they must not fall, they are not the goal.
 * Smoke and test-world are run separately and are not part of this table.
 *
 *   node scripts/landing-table.mjs [--log] [--json]       (markdown on stdout; --log appends it to worker-log.md as a new entry)
 * The same table is section "The measures that count" of docs/system-map.html (scripts/build-system-map.mjs calls `landingHtml`).
 */
import { readFileSync, readdirSync, existsSync, statSync, appendFileSync } from 'node:fs';
import { join, resolve, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import { spawnSync } from 'node:child_process';
import { readCorpus, readRuns, latest } from './lib/cases-corpus.mjs';
import { read as readIndicators } from './indicators.mjs';

const REPO = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const read = (p) => { try { return readFileSync(join(REPO, p), 'utf8'); } catch { return ''; } };
const esc = (s) => String(s).replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' })[c]);
const fmt = (n) => Number(n).toLocaleString('en-US');
const pct = (a, b) => (b ? `${Math.round((1000 * a) / b) / 10}%` : '-');

// ---- hand-written lines by kind ----------------------------------------------------------------------------------------------------------------
const codeLines = (text) => text.split('\n').filter((l) => l.trim() && !/^\s*(#|\/\/|\*|\/\*)/.test(l)).length;
/** { language, schema, code, other } hand-written lines of a world: generated files (a GENERATED header or `generated` in the name), tests.sop and vendored code are left out. */
export function linesOf(dir) {
  const out = { language: 0, schema: 0, code: 0, other: 0 };
  const walk = (d) => {
    for (const f of readdirSync(d).sort()) {
      const p = join(d, f);
      if (statSync(p).isDirectory()) { if (f !== 'vendor' && f !== 'node_modules') walk(p); continue; }
      if (!/\.(sop|mjs)$/.test(f) || /generated/i.test(f) || f === 'tests.sop') continue;
      const text = readFileSync(p, 'utf8');
      if (/GENERATED|generated by/i.test(text.split('\n').slice(0, 4).join('\n'))) continue;
      const n = codeLines(text);
      if (f.endsWith('.mjs')) out.code += n;
      else if (f === 'schema.sop') out.schema += n;
      else if (/^(patterns|lexicon|templates|operations|matrix|describe|phrases)/.test(f)) out.language += n;
      else out.other += n;
    }
  };
  walk(join(REPO, 'worlds', dir));
  return out;
}

// ---- the measures ----------------------------------------------------------------------------------------------------------------------------
function schemaWorlds() {
  const has = (root, d) => existsSync(join(REPO, root, d, 'schema.sop'));
  const list = (root) => (existsSync(join(REPO, root)) ? readdirSync(join(REPO, root)).filter((d) => has(root, d)).sort() : []);
  return { switched: list('worlds'), pilots: list('worlds-pilot') };
}

async function actCount() {
  try { const A = await import('../worlds/acts/acts.mjs'); return { acts: Object.keys(A.ACTS).length, verbGroups: Object.keys(A.ACT_VERBS ?? {}).length }; } catch { return { acts: null, verbGroups: null }; }
}

/** docs/host-boundary.md table "General lines still in PSys2": live SOP and code lines for the modules that are worlds, the doc's numbers for the rest. */
function generalLines() {
  const sec = read('docs/host-boundary.md').split(/\n## /).find((s) => s.startsWith('General lines still in PSys2')) ?? '';
  const num = (s) => { const m = /([\d,]+)/.exec(String(s)); return m ? Number(m[1].replace(/,/g, '')) : 0; };
  const WORLDS = { acts: ['acts'], space: ['space'], 'session.things': ['session.things'], 'session.dialogue': ['session.dialogue'], 'common.sense': ['common.sense'], 'meta.worlds': ['meta.worlds'], 'plan.seating, plan.timeline': ['plan.seating', 'plan.timeline'] };
  const rows = [];
  let sop = 0, code = 0, gen = 0;
  for (const line of sec.split('\n')) {
    const c = line.split('|').map((x) => x.trim());
    if (c.length < 7 || /^(module|---|\*\*total)/.test(c[1]) || !c[1]) continue;
    const dirs = WORLDS[c[1]];
    let s = num(c[2]), k = num(c[3]), live = false;
    if (dirs && dirs.every((d) => existsSync(join(REPO, 'worlds', d)))) { const l = dirs.map(linesOf); s = l.reduce((a, x) => a + x.language + x.schema + x.other, 0); k = l.reduce((a, x) => a + x.code, 0); live = true; }
    rows.push({ module: c[1], sop: s, code: k, generators: num(c[4]), target: c[5], live });
    sop += s; code += k; gen += num(c[4]);
  }
  return { rows, sop, code, generators: gen, total: sop + code + gen };
}

async function inventorySummary() {
  try {
    const inv = await import('./knowledge-inventory.mjs');
    const items = inv.counterparts(inv.inventory(), join(REPO, 'tests/fixtures/catalog')).filter((i) => !i.sample);
    return { items: items.length, words: items.reduce((a, i) => a + i.size, 0), withCounterpart: items.filter((i) => i.counterpart !== 'none').length };
  } catch { return null; }
}

function gridSummary() {
  const f = join(REPO, 'docs/webchat/coverage-grid.json');
  if (!existsSync(f)) return null;
  const g = JSON.parse(readFileSync(f, 'utf8'));
  const worlds = g.worlds.map((w) => ({ id: w.id, total: w.cells.length, holes: w.cells.filter((c) => c.ops === 'miss' || c.matrix === 'miss').length }));
  return { worlds, total: worlds.reduce((a, w) => a + w.total, 0), holes: worlds.reduce((a, w) => a + w.holes, 0) };
}

const tally = (rows) => { const t = { right: 0, wrong: 0, na: 0, unchecked: 0 }; for (const r of rows) t[r.outcome] = (t[r.outcome] ?? 0) + 1; return t; };
const tallyText = (t) => `${t.right} right / ${t.wrong} wrong${t.na ? ` / ${t.na} said plainly` : ''}${t.unchecked ? ` / ${t.unchecked} unchecked` : ''}`;

/** The table as data: { rows: [{ label, value, detail }], guard: [{ label, value }], notes }. `meas` and `worlds` come from build-system-map when it is the caller. */
export async function compute({ meas, worlds } = {}) {
  if (!worlds || !meas) {   // standalone; build-system-map passes both (importing it from inside its own run would never settle)
    const sm = await import('./build-system-map.mjs');
    worlds ??= sm.collectWorlds().worlds;
    meas ??= await sm.measure();
  }
  const sw = schemaWorlds(), acts = await actCount();
  const tabs = worlds.filter((w) => w.group === 'tab');
  const tabLines = tabs.map((w) => ({ id: w.id, ...linesOf(w.id) })).sort((a, b) => b.language - a.language);
  const lang = tabLines.reduce((a, w) => a + w.language, 0);
  const gl = generalLines(), inv = await inventorySummary(), grid = gridSummary();
  const reuseRows = worlds.filter((w) => w.reuseRow);
  const reuseMean = reuseRows.length ? reuseRows.reduce((a, w) => a + w.reuse, 0) / reuseRows.length : null;
  const rows = [];
  rows.push({ label: 'Worlds on schema + acts', value: String(sw.switched.length), detail: `${sw.switched.join(', ')}${sw.pilots.length ? `; pilot, not switched: ${sw.pilots.join(', ')}` : ''}${acts.acts != null ? `; ${acts.acts} acts, ${acts.verbGroups} verb groups in worlds/acts` : ''}` });
  rows.push({ label: 'Hand-written language lines in tab worlds', value: fmt(lang), detail: `${tabs.length} tab worlds; most: ${tabLines.filter((w) => w.language).slice(0, 5).map((w) => `${w.id} ${fmt(w.language)}`).join(', ')}; with code: ${fmt(tabLines.reduce((a, w) => a + w.code, 0))} lines of .mjs, ${fmt(tabLines.reduce((a, w) => a + w.schema, 0))} of schema` });
  rows.push({ label: 'General lines still in PSys2', value: fmt(gl.total), detail: `SOP ${fmt(gl.sop)}, code ${fmt(gl.code)}, generators ${fmt(gl.generators)} (docs/host-boundary.md; the world modules counted live)${inv ? `; knowledge still in worlds: ${inv.items} items, ${fmt(inv.words)} words (${inv.withCounterpart} with a catalog counterpart)` : ''}` });
  rows.push({ label: 'Reuse number per world (mean)', value: reuseMean == null ? '-' : reuseMean.toFixed(2), detail: `${reuseRows.length} worlds in the library report; ${reuseRows.filter((w) => w.reuse > 0).map((w) => `${w.id} ${w.reuse}`).join(', ') || 'none above 0'}; the rest 0` });
  rows.push({ label: 'Coverage grid holes', value: grid ? `${grid.holes} of ${fmt(grid.total)}` : '-', detail: grid ? `judged by the state difference (k.actions verbs x kinds x values): ${grid.worlds.map((w) => `${w.id}${sw.pilots.includes(w.id) && !sw.switched.includes(w.id) ? ' (pilot)' : ''} ${w.holes}/${w.total}`).join(', ')}` : 'no docs/webchat/coverage-grid.json' });

  const corpus = readCorpus(), last = latest(corpus), cases = [...last.values()];
  const helped = Object.values(meas.perWorld).reduce((a, w) => a + w.helped, 0), turns = Object.values(meas.perWorld).reduce((a, w) => a + w.turns, 0);
  const crossGroups = cases.filter((c) => c.outcome === 'wrong' && /^(wrong world routing|foreign-world reading)/.test(c.group ?? ''));
  const transferWrong = cases.filter((c) => c.kind === 'transfer' && c.outcome === 'wrong');
  rows.push({ label: 'Cross-world turns', value: `${helped} of ${turns}`, detail: `owner logs: turns answered with help of another world or the catalog (fill, lookup, ask, layout), ${pct(helped, turns)}; ledger: ${crossGroups.length} failing cases are cross-world (wrong routing, foreign-world reading), ${transferWrong.length} transfer cells are wrong` });

  const tr = cases.filter((c) => c.kind === 'transfer' && c.pair);
  const key = (p) => p.split('>').sort().join('<>');
  const ok = new Set(tr.filter((c) => c.outcome === 'right' && c.exp !== 'T3').map((c) => key(c.pair)));
  const tried = new Set(tr.filter((c) => c.exp !== 'T3').map((c) => key(c.pair)));
  const k3 = new Set(tr.filter((c) => c.outcome === 'right' && c.exp === 'T3').map((c) => c.pair));
  const k3t = new Set(tr.filter((c) => c.exp === 'T3').map((c) => c.pair));
  rows.push({ label: 'Pairs of worlds that cooperate', value: `${ok.size} of ${tried.size}`, detail: `T1 (things) and T2 (taught facts): a pair counts when at least one cell is right in either direction (${[...ok].sort().join(', ')}); T3 (rules from the knowledge tier): ${k3.size} of ${k3t.size} world-and-knowledge pairs (${[...k3].sort().join(', ')}). T4-T6 have no experiment yet (the timeline is the T6-lite column of T1)` });

  // the scaling indicators of Q10 item 1 (owner-agreed): recorded by scripts/indicators.mjs, the captures counted here from the corpus
  const ind = readIndicators();
  if (ind.seating60) rows.push({ label: 'New world from a schema alone: natural requests right', value: `${ind.seating60.right} of ${ind.seating60.total}`, detail: `plan.seating (schema.sop only), 60 requests written without seeing the grammar (scripts/exp-seating.mjs), judged by hand ${ind.seating60.date}${ind.seating60.read != null ? `; the rules read ${ind.seating60.read} of ${ind.seating60.readOf} (${ind.seating60.readDate})` : ''}${ind.seating60.note ? `; ${ind.seating60.note}` : ''}` });
  if (ind.robustness) { const r = ind.robustness; rows.push({ label: 'Robustness sets (rules config)', value: ['typos', 'loose-words', 'paraphrases-rt'].map((k) => `${k} ${r[k].right}/${r[k].total}`).join(', '), detail: `${['typos', 'loose-words', 'paraphrases-rt'].map((k) => `${k} ${pct(r[k].right, r[k].total)}`).join(', ')}; end to end through the shared pipeline, skipped rows not counted (scripts/eval-ablation.mjs ${r.config}, ${r.date}, build ${r.build})` }); }
  const captures = cases.filter((c) => c.outcome === 'wrong' && /^(wrong world routing|foreign-world reading)/.test(c.group ?? ''));
  rows.push({ label: 'Cross-world captures (target 0)', value: String(captures.length), detail: `cases of the corpus where a world answered another world's sentence or the wrong world took it (groups "foreign-world reading" ${captures.filter((c) => /^foreign/.test(c.group)).length}, "wrong world routing" ${captures.filter((c) => /^wrong world/.test(c.group)).length}); the invariants test and test-world catch them at the landing` });
  if (ind.richest?.total) rows.push({ label: 'Richest world on acts: its own tests', value: `${ind.richest.world} ${pct(ind.richest.right, ind.richest.total)}`, detail: `${ind.richest.right} of ${ind.richest.total} tests of ${ind.richest.world}${ind.richest.where === 'worlds-pilot' ? ' (the schema pilot, worlds-pilot)' : ' (the switched world)'}, ${ind.richest.schemaLines} schema lines; the switch of the world to schema + acts is the proof (${ind.richest.date})` });

  const runs = readRuns(), lastRun = runs.at(-1);
  const kinds = {}; for (const c of cases) kinds[c.kind] = (kinds[c.kind] ?? 0) + 1;
  const stage = {}; for (const c of cases.filter((x) => x.outcome === 'wrong')) stage[c.stage ?? '?'] = (stage[c.stage ?? '?'] ?? 0) + 1;
  rows.push({ label: 'Cases in the corpus', value: fmt(cases.length), detail: `${Object.entries(kinds).map(([k, n]) => `${k} ${fmt(n)}`).join(', ')}; failing view ${fmt(cases.filter((c) => c.outcome === 'wrong').length)} (by stage: ${Object.entries(stage).sort((a, b) => b[1] - a[1]).map(([k, n]) => `${k} ${n}`).join(', ')}); last run ${lastRun ? `${lastRun.run}: ${lastRun.added} added, ${lastRun.regressions.length} right-to-wrong, ${lastRun.fixed.length} wrong-to-right` : 'none'}` });

  const owner = (sfx) => tally(cases.filter((c) => c.kind !== 'grid' && c.source?.startsWith(`owner-log-2026-11-13${sfx}#`)));
  const t = (exp) => tally(cases.filter((c) => c.kind === 'transfer' && c.exp === exp && c.tab !== undefined));
  const guard = [
    { label: 'Owner log a / b / c (replayed)', value: `a: ${tallyText(owner(''))}; b: ${tallyText(owner('b'))}; c: ${tallyText(owner('c'))}` },
    { label: 'T1 things / T2 taught facts / T3 rules', value: `T1: ${tallyText(t('T1'))}; T2: ${tallyText(t('T2'))}; T3: ${tallyText(t('T3'))}` },
    { label: 'Grid judged by state or answer', value: grid ? `${grid.total - grid.holes} of ${fmt(grid.total)}` : '-' },
  ];
  return { rows, guard, regressions: lastRun?.regressions.length ?? 0 };
}

export function toMarkdown(t) {
  const cell = (s) => String(s).replace(/\|/g, '/');
  return `| measure | value | detail |\n| --- | --- | --- |\n${t.rows.map((r) => `| ${cell(r.label)} | ${cell(r.value)} | ${cell(r.detail)} |`).join('\n')}\n\nGuard (accuracy sets, must not fall, not the goal):\n\n| set | result |\n| --- | --- |\n${t.guard.map((g) => `| ${cell(g.label)} | ${cell(g.value)} |`).join('\n')}\n`;
}

export function toHtml(t) {
  return `<h2>The measures that count</h2>
<p>The one table reported at every landing. Generated by <code>scripts/landing-table.mjs</code> from the repository, the case corpus (<code>training/eval/cases.jsonl</code>, <code>scripts/update-cases.mjs</code>) and the coverage grid; nothing in it is typed. Accuracy sets are only a guard.</p>
<div class="scroll"><table><thead><tr><th>measure</th><th class="num">value</th><th>detail</th></tr></thead><tbody>
${t.rows.map((r) => `<tr><td>${esc(r.label)}</td><td class="num big">${esc(r.value)}</td><td style="white-space:normal;min-width:24rem">${esc(r.detail)}</td></tr>`).join('\n')}</tbody></table></div>
<p><b>Guard</b> (must not fall; not the goal)</p>
<div class="scroll"><table><thead><tr><th>set</th><th>result</th></tr></thead><tbody>
${t.guard.map((g) => `<tr><td>${esc(g.label)}</td><td style="white-space:normal">${esc(g.value)}</td></tr>`).join('\n')}</tbody></table></div>
`;
}

export async function landingHtml(args) { return toHtml(await compute(args)); }

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const t = await compute();
  const md = toMarkdown(t);
  if (process.argv.includes('--json')) console.log(JSON.stringify(t, null, 1));
  else console.log(md);
  if (process.argv.includes('--log')) {
    const build = spawnSync('git', ['rev-parse', '--short', 'HEAD'], { cwd: REPO, encoding: 'utf8' }).stdout.trim();
    appendFileSync(join(REPO, 'worker-log.md'), `\n## ${new Date().toISOString().slice(0, 10)} LANDING TABLE (generated by scripts/landing-table.mjs at ${build})\n\n${md}\n`);
    console.error('appended to worker-log.md');
  }
}
